  ('4d5c8297-676e-5144-8466-3e0d262b4c9e', '0bf3870c-9f64-5e1a-a82f-925dc39f23f0', 5, 'skriv', 'Skriv ''hus'' på engelska.', null, '["house"]'::jsonb, 'Hus heter house. Hem heter home.'),
  ('21952c81-3b1f-578d-9463-df019cccfe1c', '0bf3870c-9f64-5e1a-a82f-925dc39f23f0', 6, 'para', 'Para ihop rummet på engelska med rummet på svenska.', null, '[["bedroom","sovrum"],["bathroom","badrum"],["living room","vardagsrum"],["garden","trädgård"]]'::jsonb, 'Bed är säng, så bedroom är sovrum. Bath är bad, så bathroom är badrum. Living room är vardagsrum, och garden är trädgård.'),
  ('5fa51222-9d45-58f2-a23e-c5826ab4943b', '0bf3870c-9f64-5e1a-a82f-925dc39f23f0', 7, 'val', '''Chair'' betyder bord.', '["Sant","Falskt"]'::jsonb, '1'::jsonb, 'Chair betyder stol. Bord heter table.'),
  ('e1d39759-ee09-5e2b-a177-211bb250774f', '0bf3870c-9f64-5e1a-a82f-925dc39f23f0', 8, 'ordna', 'Bygg meningen: Boken ligger på bordet.', null, '["The","book","is","on","the","table."]'::jsonb, 'På bordet heter on the table. Boken och bordet får båda the framför sig.'),
  ('e04e022c-3f88-5584-963e-0d53cb6eb5a0', 'a7b0dcf9-a50d-5f76-af70-7c0b44d35cf0', 1, 'val', 'Vad betyder ''swim''?', '["simma","springa","sjunga"]'::jsonb, '0'::jsonb, 'Swim betyder simma. Springa heter run och sjunga heter sing.'),
  ('1d8f69fe-0810-5845-b03e-efa2ee1986c3', 'a7b0dcf9-a50d-5f76-af70-7c0b44d35cf0', 2, 'val', 'Vad heter ''hoppa'' på engelska?', '["jump","run","sleep","eat"]'::jsonb, '0'::jsonb, 'Hoppa heter jump. Run är springa, sleep är sova och eat är äta.'),
  ('e5add798-4b64-5418-bc7a-b8a6a8c782f7', 'a7b0dcf9-a50d-5f76-af70-7c0b44d35cf0', 3, 'val', 'Vad betyder ''sleep''?', '["sova","äta","läsa"]'::jsonb, '0'::jsonb, 'Sleep betyder sova. Äta heter eat och läsa heter read.'),
  ('8a0153a6-4622-5f94-a8fc-f198b8bb5226', 'a7b0dcf9-a50d-5f76-af70-7c0b44d35cf0', 4, 'skriv', 'Skriv ''äta'' på engelska.', null, '["eat"]'::jsonb, 'Äta heter eat.'),
  ('8ff3cc2b-df51-50d2-a800-da4754c1405b', 'a7b0dcf9-a50d-5f76-af70-7c0b44d35cf0', 5, 'skriv', 'Skriv ''springa'' på engelska.', null, '["run"]'::jsonb, 'Springa heter run.'),
  ('0585df91-8ae0-5351-a948-61522260ec55', 'a7b0dcf9-a50d-5f76-af70-7c0b44d35cf0', 6, 'para', 'Para ihop verbet på engelska med verbet på svenska.', null, '[["read","läsa"],["write","skriva"],["sing","sjunga"],["dance","dansa"]]'::jsonb, 'Read är läsa, write är skriva, sing är sjunga och dance är dansa. I write hörs inte w:et.'),
