  ('81347759-77a8-59f1-a2df-3109185c0cd1', 'd4ebc9e5-0467-5cb6-9090-30d48a928840', 7, 'ordna', 'Bygg meningen: Det här är min mamma.', null, '["This","is","my","mum."]'::jsonb, 'Det här är heter this is. Min heter my.'),
  ('893fb67b-eeee-5c54-8859-7349752c6781', 'd4ebc9e5-0467-5cb6-9090-30d48a928840', 8, 'ordna', 'Bygg meningen: Hennes hund är liten.', null, '["Her","dog","is","small."]'::jsonb, 'Hennes heter her, och det står före hunden, precis som på svenska.'),
  ('185f7c1a-59c2-5ba1-a836-65deee39394f', '08b771b6-43a5-5b9c-9e74-52131ef481ff', 1, 'ordna', 'Bygg meningen: Jag har en röd boll.', null, '["I","have","a","red","ball."]'::jsonb, 'Färgen står före saken, precis som på svenska: a red ball.'),
  ('7b79eeab-e43b-5b3e-8b08-f8798a790e66', '08b771b6-43a5-5b9c-9e74-52131ef481ff', 2, 'ordna', 'Bygg meningen: Katten är stor.', null, '["The","cat","is","big."]'::jsonb, 'Katten heter the cat. På engelska står the före ordet.'),
